Tool response:
Tool: create_form_field
Description: Adds a new field to an existing application form. The field must be of type 'dropdown' and marked as required.
Parameters:
    {
      "type": "object",
      "properties": {
        "form_id": {
          "type": "integer",
          "description": "ID of the application form to add the field to",
          "title": "Form Id"
        },
        "field_name": {
          "type": "string",
          "title": "Field Name"
        },
        "field_type": {
          "type": "string",
          "title": "Field Type"
        },
        "is_required": {
          "type": "boolean",
          "title": "Is Required"
        }
      },
      "required": [
        "form_id",
        "field_name",
        "field_type",
        "is_required"
      ]
    }

Tool response:
Tool: create_dropdown_option
Description: Creates a new dropdown option for a specified dropdown field.
Parameters:
    {
      "type": "object",
      "properties": {
        "field_id": {
          "type": "integer",
          "description": "ID of the dropdown field to add the option to",
          "title": "Field Id"
        },
        "option_value": {
          "type": "string",
          "title": "Option Value"
        }
      },
      "required": [
        "field_id",
        "option_value"
      ]
    }
